sid=mujoco.mj_name2id(m,mujoco.mjtObj.mjOBJ_SITE,'robot_pinch_site');qids=np.array([m.jnt_qposadr[mujoco.mj_name2id(m,mujoco.mjtObj.mjOBJ_JOINT,f'robot_joint_{j}')] for j in range(1,8)]);dofs=np.array([m.jnt_dofadr[mujoco.mj_name2id(m,mujoco.mjtObj.mjOBJ_JOINT,f'robot_joint_{j}')] for j in range(1,8)]);slide=m.jnt_qposadr[mujoco.mj_name2id(m,mujoco.mjtObj.mjOBJ_JOINT,'kitchen_island_drawer_s1c1_joint')]
a=[]
def step(act):s.step(act);a.append(act.copy())
for _ in range(5):act=np.zeros(11);act[0]=.1;step(act)
q1=np.array([.14060003,.96635877,3.11933864,-1.79957801,.02607309,-.29813234,1.67377148])
for i in range(150):
 act=np.zeros(11);act[3:10]=np.clip(q1-d.qpos[qids],-.1,.1);step(act)
 if np.linalg.norm(d.qpos[qids]-q1)<.02 and i>30:break
print('stage1 t',i,'p',d.site_xpos[sid],'qerr',d.qpos[qids]-q1)
t=np.array([.925,0,.335]);qgoal=d.qpos[qids].copy()
for i in range(300):
 p=d.site_xpos[sid].copy();err=t-p;Jp=np.zeros((3,m.nv));Jr=np.zeros((3,m.nv));mujoco.mj_jacSite(m,d,Jp,Jr,sid);J=Jp[:,dofs]
 dq=J.T@np.linalg.solve(J@J.T+0.0002*np.eye(3),err*.5)
 qgoal+=np.clip(dq,-.04,.04)
 act=np.zeros(11);act[3:10]=np.clip(qgoal-d.qpos[qids],-.1,.1);step(act)
 if i%25==24:print('servo',i+1,'p',np.round(d.site_xpos[sid],3),'err',np.round(err,3),'qerr',np.round(qgoal-d.qpos[qids],2),'slide',d.qpos[slide])
for _ in range(30):act=np.zeros(11);act[10]=1;step(act)
print('closed',d.site_xpos[sid], 'slide',d.qpos[slide], 'contacts')
for i in range(d.ncon):
 c=d.contact[i];g1=int(c.geom1);g2=int(c.geom2);n1=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_BODY,int(m.geom_bodyid[g1]));n2=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_BODY,int(m.geom_bodyid[g2]))
 if 'robot' in str(n1) or 'robot' in str(n2):print(n1,n2,round(c.dist,4))
for i in range(1):act=np.zeros(11);act[0]=.1;act[10]=1;step(act);print('pull',d.qpos[m.jnt_qposadr[mujoco.mj_name2id(m,mujoco.mjtObj.mjOBJ_JOINT,'robot_joint_x')],],d.qpos[slide])
s.save_trajectory(a,'/app/output/trajectory.npz');np.save('/tmp/stage1servo.npy',a);print('steps',len(a))
